# import
import json
import os
import sys
import zipfile
from fractions import Fraction
# costanti
filename = './esempi/esempio.xlsx' # file dove sono salvati gli esiti della elezione: .xlsx (export di Microsoft Forms) o .xls
# colonne 0-indexed del foglio excel: per ciascuna votazione la scelta iniziale e l'ordinamento
colonnaSceltaDirettivo = 5 # scelta tra voto valido, scheda bianca e scheda nulla (prima votazione)
colonnaDirettivo = 6 # ordinamento per il Direttivo (prima votazione)
colonnaSceltaPriorita = 7 # scelta tra voto valido, scheda bianca e scheda nulla (seconda votazione)
colonnaPriorita = 8 # ordinamento per le cariche (seconda votazione)
# opzioni della scelta iniziale, scritte esattamente come nel modulo
sceltaValido = "Voto valido"
sceltaBianca = "Scheda bianca"
sceltaNulla = "Scheda nulla"
cariche = ["Presidente", "Vicepresidente", "Segretario", "Tesoriere"]
# candidati validi, scritti esattamente come compaiono nelle risposte esportate dal modulo,
# ciascuno con le cariche dichiarate nella candidatura in ordine di preferenza (al più due)
candidati = {
    # "Mario Rossi": ["Presidente", "Tesoriere"],
    # "Anna Bianchi": [],
}
# candidati ritirati dopo il termine di verifica delle candidature, scritti come in candidati:
# restano sulla scheda e contano per il numero dei seggi, ma sono esclusi prima del primo turno di entrambe le votazioni
ritirati = []
# ordine di spareggio di tutti i candidati, stabilito e comunicato prima del voto:
# prima la maggiore anzianità di iscrizione, poi il più giovane, poi l'ordine estratto a sorte
priorita = []
# numero di seggi del Direttivo in base al numero di candidati
def numeroSeggi(numeroCandidatiParam):
    if numeroCandidatiParam > 6:
        return 7
    if numeroCandidatiParam >= 5:
        return 5
    return 0 # sotto i 5 candidati le elezioni non si possono tenere
# quota di Droop: voti necessari per essere eletti
def quotaDroop(votiValidiParam, seggiParam):
    return votiValidiParam // (seggiParam + 1) + 1
# sceglie il candidato con il punteggio più alto (o più basso se peggioreParam);
# a parità prevale chi viene prima in priorita
def scegli(candidatiParam, punteggiParam, peggioreParam=False):
    if peggioreParam:
        return min(candidatiParam, key=lambda x: (punteggiParam[x], -priorita.index(x)))
    return min(candidatiParam, key=lambda x: (-punteggiParam[x], priorita.index(x)))
# lettura delle righe del file degli esiti, in base all'estensione: .xlsx (export di Microsoft Forms) o .xls
# restituisce una lista di righe, ciascuna lista di valori; la prima riga e' l'intestazione
def leggiRighe(filenameParam):
    estensione = os.path.splitext(filenameParam)[1].lower()
    if estensione not in ('.xlsx', '.xls'):
        print(f"Errore: estensione '{estensione}' non supportata, usare .xlsx o .xls.")
        sys.exit(1)
    if not os.path.isfile(filenameParam):
        print(f"Errore: Il file '{filenameParam}' non esiste.")
        sys.exit(1)
    # le librerie si importano solo quando servono: xlrd e' necessaria solo per i file .xls
    try:
        if estensione == '.xlsx':
            import openpyxl
            from openpyxl.utils.exceptions import InvalidFileException
            erroriFile = (InvalidFileException, zipfile.BadZipFile, KeyError, OSError)
        else:
            import xlrd
            erroriFile = (xlrd.XLRDError, OSError)
    except ImportError as e:
        print(f"Errore: manca la libreria '{e.name}', installare le dipendenze con: pip install -r codice/requirements.txt")
        sys.exit(1)
    try:
        if estensione == '.xlsx':
            # caricamento completo e non read_only: in read_only openpyxl si fida delle dimensioni dichiarate
            # nel foglio, che se errate tagliano righe e colonne
            foglio = openpyxl.load_workbook(filenameParam, data_only=True).worksheets[0]
            return [list(riga) for riga in foglio.iter_rows(values_only=True)]
        sheet = xlrd.open_workbook(filenameParam).sheet_by_index(0)
        return [sheet.row_values(i) for i in range(sheet.nrows)]
    except erroriFile as e:
        print(f"Errore durante l'apertura del file: {e}")
        sys.exit(1)
# valore di una cella come testo, vuoto se la cella non esiste o e' vuota
def valoreCella(rigaParam, colonnaParam):
    if colonnaParam >= len(rigaParam) or rigaParam[colonnaParam] is None:
        return ''
    return str(rigaParam[colonnaParam]).strip()
# estrazione delle schede di una votazione: liste ordinate di candidati, dalla preferenza più alta alla più bassa;
# la scelta iniziale decide se la scheda è bianca, nulla o un voto da leggere nella colonna dell'ordinamento
def getSchede(righeParam, colonnaSceltaParam, colonnaParam):
    schedeResult = []
    schedeBianche = 0
    schedeNulle = 0
    # per tutte le righe saltando l'intestazione
    i = 1
    while i < len(righeParam):
        # le righe del tutto vuote (per esempio in fondo al foglio, se formattate in Excel) non sono schede
        if all(valoreCella(righeParam[i], c) == '' for c in range(len(righeParam[i]))):
            i = i + 1
            continue
        scelta = valoreCella(righeParam[i], colonnaSceltaParam)
        if scelta not in (sceltaValido, sceltaBianca, sceltaNulla):
            print(f"Errore: scelta '{scelta}' (riga {i + 1}) non riconosciuta, controllare colonne e opzioni.")
            sys.exit(1)
        # con scheda bianca o nulla l'eventuale ordinamento non si legge
        if scelta == sceltaBianca:
            schedeBianche = schedeBianche + 1
        elif scelta == sceltaNulla:
            schedeNulle = schedeNulle + 1
        else:
            # cella in cui è salvato l'ordinamento, dalla preferenza più alta alla più bassa
            valoreCellaPreferenze = valoreCella(righeParam[i], colonnaParam)
            scheda = [p.strip() for p in valoreCellaPreferenze.split(';') if p.strip()]
            for p in scheda:
                if p not in candidati:
                    print(f"Errore: '{p}' (riga {i + 1}) non è tra i candidati validi.")
                    sys.exit(1)
            # voto valido senza ordinamento o con un candidato ripetuto: scheda nulla
            if not scheda or len(set(scheda)) != len(scheda):
                schedeNulle = schedeNulle + 1
            else:
                schedeResult.append(scheda)
        # passiamo alla prossima riga (voto)
        i = i + 1
    return schedeResult, schedeBianche, schedeNulle
# voto singolo trasferibile (STV) con quota di Droop e trasferimento frazionario delle eccedenze
# restituisce gli eletti in ordine di elezione, i non eletti in gruppi in ordine di esclusione
# (nello stesso gruppo a pari merito), la quota e il resoconto dei turni di scrutinio; i ritirati non sono né gli uni né gli altri
def calcolaSTV(schedeParam, seggiParam, candidatiParam):
    quota = quotaDroop(len(schedeParam), seggiParam)
    pesi = [Fraction(1)] * len(schedeParam) # ogni scheda vale 1 all'inizio
    inGara = set(candidatiParam) - set(ritirati) # né eletti né esclusi; i ritirati non entrano in gara
    eletti = []
    esclusi = []
    turni = []
    while inGara:
        # ogni scheda va al primo candidato ancora in gara nel suo ordinamento
        conteggi = {c: Fraction(0) for c in inGara}
        preferenzaScheda = {}
        for i, scheda in enumerate(schedeParam):
            for c in scheda:
                if c in inGara:
                    preferenzaScheda[i] = c
                    conteggi[c] += pesi[i]
                    break
        # resoconto in ordine di voti, a parità nell'ordine di spareggio: è lo stesso a ogni esecuzione
        turno = {"voti": {c: round(float(v), 4) for c, v in sorted(conteggi.items(), key=lambda x: (-x[1], priorita.index(x[0])))}}
        turni.append(turno)
        liberi = seggiParam - len(eletti)
        # seggi esauriti: chi resta in gara non è eletto e segue gli esclusi, in ordine di voti
        if liberi == 0:
            for v in sorted(set(conteggi.values())):
                esclusi.append(sorted((c for c in inGara if conteggi[c] == v), key=priorita.index))
            turno["non eletti"] = sorted(inGara, key=lambda x: (-conteggi[x], priorita.index(x)))
            break
        # se restano tanti candidati quanti seggi liberi, sono tutti eletti (qui le parità non contano)
        if len(inGara) <= liberi:
            turno["eletti"] = sorted(inGara, key=lambda x: (-conteggi[x], priorita.index(x)))
            eletti.extend(turno["eletti"])
            break
        # eletto il candidato sopra quota con più voti
        sopraQuota = [c for c in inGara if conteggi[c] >= quota]
        if sopraQuota:
            c = scegli(sopraQuota, conteggi)
            eccedenza = conteggi[c] - quota
            # le schede che lo sostengono passano ai candidati successivi con peso ridotto
            for i in preferenzaScheda:
                if preferenzaScheda[i] == c:
                    pesi[i] = pesi[i] * eccedenza / conteggi[c]
            eletti.append(c)
            inGara.remove(c)
            turno["eletti"] = [c]
        # nessuno sopra quota: escluso il candidato con meno voti, le sue schede passano oltre con il loro peso;
        # i candidati senza voti si escludono insieme, se ne restano abbastanza per i seggi liberi
        else:
            senzaVoti = sorted((c for c in inGara if conteggi[c] == 0), key=priorita.index)
            if senzaVoti and len(inGara) - len(senzaVoti) >= liberi:
                gruppo = senzaVoti
            else:
                gruppo = [scegli(inGara, conteggi, peggioreParam=True)]
            esclusi.append(gruppo)
            inGara.difference_update(gruppo)
            turno["esclusi"] = gruppo
    return eletti, esclusi, quota, turni
# ordine di priorità tra gli eletti: STV a un seggio ripetuto, togliendo ogni volta chi è già in graduatoria
def calcolaPriorita(schedeParam, elettiParam):
    # dalla seconda votazione si tengono solo gli eletti, mantenendo il loro ordine relativo
    schede = [[c for c in scheda if c in elettiParam] for scheda in schedeParam]
    schede = [scheda for scheda in schede if scheda]
    ordine = []
    resoconto = []
    rimanenti = list(elettiParam)
    while rimanenti:
        vincitore, _, quota, turni = calcolaSTV(schede, 1, rimanenti)
        ordine.append(vincitore[0])
        rimanenti.remove(vincitore[0])
        resoconto.append({"posizione": len(ordine), "quota": quota, "turni": turni})
    return ordine, resoconto
# assegnazione delle cariche (art. 13 dello Statuto): seguendo l'ordine di priorità,
# a ciascun eletto va la carica preferita tra quelle dichiarate ancora vacante
def assegnaCariche(ordineParam):
    assegnazione = {}
    for c in ordineParam:
        for carica in candidati[c]:
            if carica not in assegnazione:
                assegnazione[carica] = c
                break
    return {carica: assegnazione.get(carica) for carica in cariche} # None: vacante, la assegna il Direttivo
# controllo delle costanti compilate prima dello scrutinio: restituisce il messaggio di errore, o None se sono valide
def controllaCostanti():
    for c in candidati:
        dichiarate = candidati[c]
        if len(dichiarate) > 2 or any(carica not in cariche for carica in dichiarate) or len(set(dichiarate)) != len(dichiarate):
            return f"Errore: cariche dichiarate non valide per '{c}'."
    if sorted(priorita) != sorted(candidati):
        return "Errore: 'priorita' deve contenere tutti i candidati, ciascuno una sola volta."
    if any(c not in candidati for c in ritirati) or len(set(ritirati)) != len(ritirati):
        return "Errore: 'ritirati' deve contenere solo candidati validi, ciascuno una sola volta."
    # i seggi si contano su tutti i candidati validi, compresi i ritirati
    if numeroSeggi(len(candidati)) == 0:
        return "Errore: meno di 5 candidati, le elezioni non si possono tenere."
    return None
# main
if __name__ == '__main__':
    errore = controllaCostanti()
    if errore:
        print(errore)
        sys.exit(1)
    # i seggi si contano su tutti i candidati validi, compresi i ritirati
    seggi = numeroSeggi(len(candidati))
    righe = leggiRighe(filename)
    # prima votazione: i membri del Direttivo schedeDirettivo, biancheDirettivo, nulleDirettivo = getSchede(righe, colonnaSceltaDirettivo, colonnaDirettivo) direttivo, esclusi, quotaDirettivo, turniDirettivo = calcolaSTV(schedeDirettivo, seggi, candidati)
    # seconda votazione: l'ordine di priorità tra i soli eletti, poi le cariche schedePriorita, biancheSeconda, nulleSeconda = getSchede(righe, colonnaSceltaPriorita, colonnaPriorita) ordinePriorita, resocontoPriorita = calcolaPriorita(schedePriorita, direttivo)
    esiti = {
        "direttivo": {
            "schede valide": len(schedeDirettivo), "schede bianche": biancheDirettivo, "schede nulle": nulleDirettivo, "seggi": seggi, "seggi non assegnati": seggi - len(direttivo), "ritirati": ritirati, "quota di Droop": quotaDirettivo, "eletti in ordine di elezione": direttivo, "non eletti in ordine di subentro (stesso gruppo: pari voti)": esclusi[::-1], "turni": turniDirettivo
        }, "cariche": {
            "schede valide": len(schedePriorita), "schede bianche": biancheSeconda, "schede nulle": nulleSeconda, "ordine di priorità": ordinePriorita, "assegnazione": assegnaCariche(ordinePriorita), "turni": resocontoPriorita
        }
    }
    if len(direttivo) < seggi:
        print(f"Attenzione: {seggi - len(direttivo)} seggi non assegnati, perché i ritiri lasciano meno candidati dei seggi.", file=sys.stderr)
    print(json.dumps(esiti, indent=2, ensure_ascii=False)) # stampa
